    });
}

app.MapPut("/api/orders/{id:guid}", async (
    Guid id, UpdateOrderRequest req, AppDbContext db, CancellationToken ct) =>
{
    var order = await db.Orders.AsTracking().FirstOrDefaultAsync(o => o.Id == id, ct);
    if (order is null) return Results.NotFound();

    // Client must send RowVersion from their last read
    if (!req.RowVersion.SequenceEqual(order.RowVersion))
        return Results.Problem(statusCode: 409, title: "Stale data", detail: "Reload and retry.");

    order.Notes = req.Notes;
    order.Total = req.Total;

    try
    {
        await db.SaveChangesAsync(ct);
        return Results.Ok(order);
    }
    catch (DbUpdateConcurrencyException)
    {
        return Results.Problem(statusCode: 409, title: "Concurrency conflict",
            detail: "Another user modified this order.");
    }
});

